components.css:
.ds-btn-primary { appearance: none; font-family: "Noto Sans SC", "PingFang SC", "Noto Sans", sans-serif; font-weight: 600; font-size: 1.0625rem; min-height: 44px; min-width: 7.5rem; padding: 0 18px; border-radius: 4px; cursor: pointer; background: var(--cinnabar, #8E2A22); color: var(--bone, #F3EEE6); border: 1px solid var(--cinnabar, #8E2A22); transition: background-color 160ms var(--ease, cubic-bezier(0.16, 1, 0.3, 1)), border-color 160ms var(--ease, cubic-bezier(0.16, 1, 0.3, 1)), transform 160ms var(--ease, cubic-bezier(0.16, 1, 0.3, 1)); }
.ds-btn-primary:hover:not(:disabled) { background: var(--cinnabar-deep, #731F19); border-color: var(--cinnabar-deep, #731F19); }
.ds-btn-primary:active:not(:disabled) { transform: translateY(1px); }
.ds-btn-primary:focus-visible { outline: 2px solid var(--cinnabar, #8E2A22); outline-offset: 3px; }
.ds-btn-primary:disabled { background: var(--lacquer, #1A1410); border-color: var(--lacquer, #1A1410); color: var(--bone, #F3EEE6); cursor: default; }

.ds-btn-ghost { appearance: none; font-family: "Noto Sans SC", "PingFang SC", "Noto Sans", sans-serif; font-weight: 600; font-size: 1.0625rem; min-height: 44px; padding: 0 18px; border-radius: 4px; cursor: pointer; background: transparent; color: var(--ink, #1A1410); border: 1px solid #C9BFB2; transition: background-color 160ms var(--ease, cubic-bezier(0.16, 1, 0.3, 1)), border-color 160ms var(--ease, cubic-bezier(0.16, 1, 0.3, 1)), transform 160ms var(--ease, cubic-bezier(0.16, 1, 0.3, 1)); }
.ds-btn-ghost:hover { background: #E9E2D8; }
.ds-btn-ghost:active { transform: translateY(1px); }
.ds-btn-ghost:focus-visible { outline: 2px solid var(--cinnabar, #8E2A22); outline-offset: 3px; }

.ds-top { display: flex; align-items: center; justify-content: space-between; gap: 24px; min-height: 72px; padding: 0 24px; background: var(--lacquer, #1A1410); color: var(--bone, #F3EEE6); }
.ds-brand { color: var(--bone, #F3EEE6); text-decoration: none; font-family: "Noto Serif SC", "Songti SC", "Noto Serif", serif; font-weight: 600; font-size: 1.35rem; letter-spacing: -0.03em; line-height: 1; }
.ds-nav { display: flex; gap: 4px 22px; }
.ds-nav-link { color: var(--bone, #F3EEE6); text-decoration: none; font-family: "Noto Sans SC", "PingFang SC", "Noto Sans", sans-serif; font-size: 0.95rem; line-height: 1.2; padding: 8px 0; box-shadow: inset 0 -2px 0 transparent; }
.ds-nav-link[aria-current="page"] { box-shadow: inset 0 -2px 0 var(--cinnabar, #8E2A22); }
.ds-nav-en { display: block; margin-top: 2px; color: #E4D5C6; font-size: 0.75rem; letter-spacing: 0.01em; }
.ds-top :focus-visible { outline: 2px solid var(--bone, #F3EEE6); outline-offset: 3px; }

.ds-cells { display: flex; gap: 8px; }
.ds-cell { width: 72px; height: 72px; display: flex; align-items: center; justify-content: center; border: 1px solid #D5CBBD; border-radius: 3px; background: var(--bone-raised, #FBF8F3); color: var(--ink, #1A1410); font-family: "Noto Sans SC", "PingFang SC", "Noto Sans", sans-serif; font-size: 1.75rem; font-weight: 600; font-variant-numeric: tabular-nums; line-height: 1; padding: 0; cursor: pointer; transition: transform 160ms var(--ease, cubic-bezier(0.16, 1, 0.3, 1)), background-color 280ms var(--ease, cubic-bezier(0.16, 1, 0.3, 1)), color 280ms var(--ease, cubic-bezier(0.16, 1, 0.3, 1)), border-color 280ms var(--ease, cubic-bezier(0.16, 1, 0.3, 1)); }
.ds-cell:hover:not(:disabled) { transform: translateY(-2px); }
.ds-cell:active:not(:disabled) { transform: translateY(0); }
.ds-cell:focus-visible { outline: 2px solid var(--cinnabar, #8E2A22); outline-offset: 3px; }
.ds-cell-target { box-shadow: inset 0 0 0 2px var(--ink, #1A1410); }

.ds-mid { width: 72px; height: 72px; display: flex; align-items: center; justify-content: center; border: 1px solid var(--cinnabar, #8E2A22); border-radius: 3px; background: var(--cinnabar, #8E2A22); color: var(--bone, #F3EEE6); font-family: "Noto Sans SC", "PingFang SC", "Noto Sans", sans-serif; font-size: 1.75rem; font-weight: 600; font-variant-numeric: tabular-nums; line-height: 1; padding: 0; cursor: pointer; transition: transform 160ms var(--ease, cubic-bezier(0.16, 1, 0.3, 1)); }
.ds-mid:hover { transform: translateY(-2px); }
.ds-mid:focus-visible { outline: 2px solid var(--cinnabar, #8E2A22); outline-offset: 3px; }

.ds-out { width: 72px; height: 72px; display: flex; align-items: center; justify-content: center; border: 1px solid transparent; border-radius: 3px; background: transparent; color: var(--ink-quiet, #5C534A); font-family: "Noto Sans SC", "PingFang SC", "Noto Sans", sans-serif; font-size: 1.75rem; font-weight: 400; font-variant-numeric: tabular-nums; line-height: 1; padding: 0; cursor: pointer; transition: transform 160ms var(--ease, cubic-bezier(0.16, 1, 0.3, 1)); }
.ds-out:hover:not(:disabled) { transform: translateY(-2px); }
.ds-out:focus-visible { outline: 2px solid var(--cinnabar, #8E2A22); outline-offset: 3px; }

.ds-track { position: relative; display: grid; grid-template-columns: repeat(3, 64px); column-gap: 8px; width: max-content; }
.ds-span { position: absolute; z-index: 0; pointer-events: none; height: 3px; border-radius: 2px; background: var(--cinnabar, #8E2A22); top: 72px; left: 0; width: 100%; transition: left 520ms var(--ease, cubic-bezier(0.16, 1, 0.3, 1)), width 520ms var(--ease, cubic-bezier(0.16, 1, 0.3, 1)), top 520ms var(--ease, cubic-bezier(0.16, 1, 0.3, 1)); }
.ds-span::before, .ds-span::after { content: ""; position: absolute; top: -4px; width: 2px; height: 11px; background: var(--cinnabar, #8E2A22); }
.ds-span::before { left: 0; }
.ds-span::after { right: 0; }
.ds-wrap { position: relative; z-index: 1; display: flex; flex-direction: column; align-items: center; gap: 18px; }
.ds-sq { width: 64px; height: 64px; display: flex; align-items: center; justify-content: center; border: 1px solid #D5CBBD; border-radius: 3px; background: var(--bone-raised, #FBF8F3); color: var(--ink, #1A1410); font-family: "Noto Sans SC", "PingFang SC", "Noto Sans", sans-serif; font-size: 1.5rem; font-weight: 600; font-variant-numeric: tabular-nums; line-height: 1; }
.ds-sq-mid { background: var(--cinnabar, #8E2A22); border-color: var(--cinnabar, #8E2A22); color: var(--bone, #F3EEE6); }
.ds-marks { min-height: 1.15rem; }
.ds-mark { font-family: "Noto Sans SC", "PingFang SC", "Noto Sans", sans-serif; font-size: 0.75rem; font-weight: 600; letter-spacing: 0.04em; line-height: 1.1; color: var(--ink, #1A1410); }
.ds-mark-mid { color: var(--cinnabar, #8E2A22); }

.ds-code { margin: 0; background: var(--bone-raised, #FBF8F3); border: 1px solid var(--line, #DDD4C8); border-radius: 4px; font-family: "JetBrains Mono", "Noto Sans Mono", ui-monospace, monospace; font-size: 0.92rem; line-height: 1.65; overflow-x: auto; }
.ds-line { display: grid; grid-template-columns: 3rem minmax(0, max-content); min-height: 1.65em; padding-right: 16px; }
.ds-line-current { background: var(--mark, #F6D5CE); }
.ds-ln { text-align: right; padding-right: 14px; color: var(--ink-quiet, #5C534A); font-variant-numeric: tabular-nums; }
.ds-line-current .ds-ln { color: var(--cinnabar, #8E2A22); }
.ds-src { white-space: pre; color: var(--ink, #1A1410); }
.ds-key { color: var(--cinnabar, #8E2A22); }

.ds-variant { display: grid; grid-template-columns: minmax(140px, 200px) minmax(0, 1fr); gap: 12px 20px; align-items: center; padding: 20px 8px; border-top: 1px solid var(--line, #DDD4C8); border-bottom: 1px solid var(--line, #DDD4C8); color: var(--ink, #1A1410); text-decoration: none; font-family: "Noto Sans SC", "PingFang SC", "Noto Sans", sans-serif; background: var(--bone, #F3EEE6); }
.ds-variant:hover { background: #E7E0D4; }
.ds-variant:focus-visible { outline: 2px solid var(--cinnabar, #8E2A22); outline-offset: 3px; }
.ds-v-zh { display: block; font-weight: 600; font-size: 1.15rem; }
.ds-v-en { display: block; margin-top: 2px; color: var(--ink-soft, #3F362F); font-size: 0.9rem; }
.ds-seq { font-variant-numeric: tabular-nums; font-weight: 600; letter-spacing: 0.04em; font-size: 1.05rem; }

.ds-tally { margin: 0; display: flex; align-items: baseline; gap: 8px; font-family: "Noto Sans SC", "PingFang SC", "Noto Sans", sans-serif; color: var(--ink, #1A1410); }
.ds-tally-k { color: var(--ink-soft, #3F362F); font-size: 0.8rem; letter-spacing: 0.08em; }
.ds-tally-n { font-variant-numeric: tabular-nums; font-weight: 600; font-size: 1.65rem; letter-spacing: -0.04em; line-height: 1; }
